import{_ as a,o as r,c as n,a2 as t}from"./chunks/framework.Lp3oD42U.js";const u=JSON.parse('{"title":"Translations","description":"","frontmatter":{},"headers":[],"relativePath":"translations.md","filePath":"translations.md"}'),o={name:"translations.md"};function s(i,e,l,h,p,d){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h1><p>Coach Poulpy is written in English first and translated from there. French is the first translation. Every word in the app, from button labels and exercise instructions to Poulpy&#39;s lines, can be proofread or translated in a web editor, without installing anything or touching code.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>A free <a href="https://github.com/signup" target="_blank" rel="noreferrer">GitHub</a> account.</li><li>The <a href="/coach-poulpy/pr-preview/pr-195/i18n/glossary/en">English rules and notes</a>: how messages are written, and what each unclear message means.</li><li>The glossary of your language, if there is one: <a href="/coach-poulpy/pr-preview/pr-195/i18n/glossary/fr">français</a>.</li></ul><h2 id="proofread-or-translate-in-fink" tabindex="-1">Proofread or translate in Fink <a class="header-anchor" href="#proofread-or-translate-in-fink" aria-label="Permalink to &quot;Proofread or translate in Fink&quot;">​</a></h2><p><a href="https://fink.inlang.com/" target="_blank" rel="noreferrer">Fink</a> is the editor translators use. It shows every message in English beside your language, and warns you when a placeholder or a plural form is missing.</p><ol><li>Open <a href="https://fink.inlang.com/?repo=tkint/coach-poulpy" target="_blank" rel="noreferrer">Coach Poulpy in Fink</a> and sign in with GitHub.</li><li>Pick your language and edit the messages you want to change.</li><li>Send your changes. Fink opens a pull request, which is a proposal the team reviews before anything reaches the app.</li></ol><p>Your changes show up in the app&#39;s next build after the pull request is merged.</p><h2 id="a-few-things-to-know" tabindex="-1">A few things to know <a class="header-anchor" href="#a-few-things-to-know" aria-label="Permalink to &quot;A few things to know&quot;">​</a></h2><ul><li><strong>Words in braces stay as they are.</strong> <code>{name}</code> or <code>{count, number}</code> is filled in by the app. You can move it, but don&#39;t translate or rename it.</li><li><strong>Plurals have one sentence per form.</strong> Fink shows a field for each form your language needs, such as one and many in French. <code>#</code> stands for the number.</li><li><strong>Type normally.</strong> A plain apostrophe, three dots and ordinary spaces are fine. Typographic apostrophes, ellipses and your language&#39;s non-breaking spaces are added automatically after your changes are merged.</li><li><strong>Poulpy is a character.</strong> He speaks in the first person, warmly, and never makes anyone feel guilty. His lines are grouped under <code>poulpy.</code> in Fink. His voice is described on the <a href="/coach-poulpy/pr-preview/pr-195/docs/brand">brand</a> page.</li><li><strong>Exercise texts come from the catalog.</strong> Their messages start with the exercise&#39;s short name, like <code>goblet-squat.name</code>. Search aliases are extra words people might type when searching. They&#39;re never shown, so add the words people really use rather than translating the English list.</li></ul><h2 id="bring-a-new-language" tabindex="-1">Bring a new language <a class="header-anchor" href="#bring-a-new-language" aria-label="Permalink to &quot;Bring a new language&quot;">​</a></h2><p>Open an <a href="https://github.com/tkint/coach-poulpy/issues/new" target="_blank" rel="noreferrer">issue</a> naming the language. The team adds it to Fink, and you can start translating from the English. Start a glossary for the language as you go: its tone (formal or informal), its typography and its key terms, like the <a href="/coach-poulpy/pr-preview/pr-195/i18n/glossary/fr">French one</a>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Every message lives in one file per language and per part of the app (app screens, shared labels, exercise catalog). The Android and iOS apps are built from those files, and so will the website and the server. The decisions behind this are <a href="/coach-poulpy/pr-preview/pr-195/docs/adr/0014-text-lives-in-one-json-file-per-language-and-namespace">ADR 0014</a> and <a href="/coach-poulpy/pr-preview/pr-195/docs/adr/0015-catalog-text-lives-in-translation-files">ADR 0015</a>. The files themselves are in the <a href="https://github.com/tkint/coach-poulpy/tree/main/i18n" target="_blank" rel="noreferrer">repository</a>.</p>',14)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
